// HasWorkProgramItem applies the HasEdge predicate on the "work_program_item" edge.
func HasWorkProgramItem() predicate.WorkProgramItemLink {
	return predicate.WorkProgramItemLink(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, WorkProgramItemTable, WorkProgramItemColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasWorkProgramItemWith applies the HasEdge predicate on the "work_program_item" edge with a given conditions (other predicates).
func HasWorkProgramItemWith(preds ...predicate.WorkProgramItem) predicate.WorkProgramItemLink {
	return predicate.WorkProgramItemLink(func(s *sql.Selector) {
		step := newWorkProgramItemStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

